import{_ as n,o as t,c as e,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-22（神经科学 / 岛叶）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-22-neuro.md","filePath":"topics/neuroscience/science-daily-2026-10-22-neuro.md"}'),s={name:"topics/neuroscience/science-daily-2026-10-22-neuro.md"};function c(i,o,g,a,l,d){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-22-神经科学-岛叶" tabindex="-1">科学日报 · 2026-10-22（神经科学 / 岛叶） <a class="header-anchor" href="#科学日报-·-2026-10-22-神经科学-岛叶" aria-label="Permalink to &quot;科学日报 · 2026-10-22（神经科学 / 岛叶）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> — 第41期 ｜ 科学板块 落盘说明：文件名带 <code>-neuro</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-22-人类岛叶的功能架构——四个亚区-一条「自上而下」调控疼痛的不对称通路" tabindex="-1">科学日报 2026-10-22：人类岛叶的功能架构——四个亚区 + 一条「自上而下」调控疼痛的不对称通路 <a class="header-anchor" href="#科学日报-2026-10-22-人类岛叶的功能架构——四个亚区-一条「自上而下」调控疼痛的不对称通路" aria-label="Permalink to &quot;科学日报 2026-10-22：人类岛叶的功能架构——四个亚区 + 一条「自上而下」调控疼痛的不对称通路&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ DOI: 10.1038/s41586-026-11175-2</p></blockquote><ul><li>问题：岛叶（insula）在<strong>疼痛、内感受、情绪</strong>中处于核心地位，但其<strong>功能架构</strong>、以及亚区之间的<strong>因果性电生理关系</strong>一直不清。</li><li>方法（罕见的人体因果手段）：<strong>87 名</strong>植入<strong>颅内电极</strong>的受试者中，把<strong>颅内电刺激（直接扰动）<strong>与</strong>任务态脑电记录</strong>结合，并在岛叶<strong>细胞构筑图谱（cytoarchitectonic atlas）<strong>内做</strong>连接性测绘</strong>。</li><li>结果（「<strong>四分区</strong>」）： <ol><li><strong>背-后区</strong>：以<strong>躯体拓扑</strong>方式编码伤害 / 温度觉与躯体感觉信号。</li><li><strong>腹-后区</strong>：可访问跨越多个身体部位的躯体信息。</li><li><strong>中-前区</strong>：与<strong>内脏感觉与焦虑状态</strong>相关。</li><li><strong>前-极区</strong>：直接刺激时<strong>近乎「沉默」</strong>，但在<strong>显著性检测与行动模式切换</strong>时强烈激活。</li></ol></li><li>关键结构（不对称性）：<strong>前-极区</strong>与包括<strong>前扣带</strong>在内的前额叶强连接，对其它岛叶区施加<strong>强而直接</strong>的影响，而从它们接受的<strong>间接输入较弱</strong> → 为「<strong>认知调控疼痛与躯体感知</strong>」给出了一条电生理通路。</li><li>结论：岛叶不是一个「感觉中继」，而是<strong>感觉编码区 + 一个自上而下控制节点</strong>的组合；且控制方向<strong>高度不对称</strong>（顶部能压底部，底部压不动顶部）。</li><li>洞察（对本库 <code>neuroscience</code>）：本库已有一条「<strong>抑制是性能来源</strong>」的硬桥（见 <code>memory/work/daily/2026-10-21.md</code> 第 1 条：PV 中间神经元 / 侧抑制消息传递）。本条补上它的<strong>结构侧</strong>：<strong>层级里的「控制强度」是不对称的</strong> —— 前-极区像<strong>控制器</strong>（输出强、输入弱），后部各区像<strong>被控对象</strong>（输出弱、输入强）。这与库内 10-19（听觉皮层 L5 树突编码抽象规则、胞体编码感觉刺激）同属「<strong>同一块皮层里，不同层级承担不同类型的变量</strong>」。对 AI 架构的迁移很直接：<strong>一个健康的系统里，「顶层设定目标」和「底层报告状态」的通道带宽不应对等</strong>；对等的双向连接往往意味着<strong>没有真正的层级</strong>（也常是噪声边泛滥的结构成因——正好呼应本库 auto_link 的假边问题）。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ 第41期 科学板块</p></blockquote><p>关键词：岛叶、insula、四分区、躯体拓扑、伤害感受、温度觉、内感受、interoception、焦虑状态、显著性检测、前-极区、前扣带、前额叶、自上而下、不对称控制、颅内电刺激、细胞构筑图谱、认知调控疼痛、控制强度不对称、层级即带宽不对称</p><p>关联：<code>topics/neuroscience/science-daily-2026-10-20.md</code>（Airscope 全皮层成像）、<code>topics/neuroscience/science-daily-2026-10-13.md</code>、<code>topics/neuroscience/science-daily-2026-09-22.md</code>、<code>topics/neuroscience/index.md</code></p>',10)])])}const m=n(s,[["render",c]]);export{p as __pageData,m as default};
